import{_ as l,E as r,h as d,c,b as e,f as t,H as n,a4 as o,w as u}from"./chunks/framework.B_fYP6Of.js";const y=JSON.parse('{"title":"Build from Ordo, not from scratch","description":"Compare two generations of Ordo and decide which durable job, review, event and streaming behaviors are worth carrying into the proposed Knowledge Lab.","frontmatter":{"title":"Build from Ordo, not from scratch","description":"Compare two generations of Ordo and decide which durable job, review, event and streaming behaviors are worth carrying into the proposed Knowledge Lab.","teaser":"A newer repository snapshot has a smaller gateway. An older one contains durable jobs and replay. The right starting point depends on which behavior you need."},"headers":[],"relativePath":"reuse/index.md","filePath":"reuse/index.md"}'),p={name:"reuse/index.md"};function h(m,a,b,f,g,v){const i=r("LabArticleHeader"),s=r("LabScroll");return d(),c("div",null,[a[1]||(a[1]=e("h1",{id:"build-from-ordo-not-from-scratch",tabindex:"-1"},[t("Build from Ordo, not from scratch "),e("a",{class:"header-anchor",href:"#build-from-ordo-not-from-scratch","aria-label":'Permalink to "Build from Ordo, not from scratch"'},"​")],-1)),n(i),a[2]||(a[2]=o('<p>Suppose the next slice must recover a queued task after restart. The current gateway at first glance looks like the natural starting point. The earlier daemon contains the durable kernel worth inspecting. Choosing between the two revisions is a question about behavior, contracts and proof.</p><p><strong>Decision guide.</strong> Application implementation remains pending.</p><p>The clean build should preserve Ordo&#39;s useful behavior while replacing the assumptions that would undermine a portable, evidence-backed research library. A new folder is not a reason to discard working ideas; an existing function is not proof that it is safe to transplant.</p><h2 id="the-important-discovery" tabindex="-1">The important discovery <a class="header-anchor" href="#the-important-discovery" aria-label="Permalink to &quot;The important discovery&quot;">​</a></h2><p>There are two substantially different implementations in <code>StudioOrdo/ordo</code>. The current rebuild contains a small Rust realtime gateway and TypeScript contracts. An accessible historical commit contains the larger Rust/SQLite daemon: DAG validation, transactional job creation, task leases, durable event replay, graph candidates and promotion records. <strong>Inspect both generations before implementing a replacement.</strong> Exact commits, paths and inspection ranges are in the <a href="./source-audit">source audit</a>.</p>',5)),n(s,{kind:"table",label:"table for The important discovery"},{default:u(()=>[...a[0]||(a[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Subsystem"),e("th",{scope:"col"},"Best starting point"),e("th",{scope:"col"},"Action")])]),e("tbody",null,[e("tr",null,[e("td",null,"Durable jobs"),e("td",null,[t("Historical "),e("code",null,"kernel.rs"),t(": DAG validation, compiled plan, idempotent creation, claims")]),e("td",null,"Extract a narrow Rust module; strengthen lease fencing and failure tests")]),e("tr",null,[e("td",null,"Durable events"),e("td",null,[t("Historical "),e("code",null,"events.rs"),t(": transactional append and cursor replay")]),e("td",null,"Adapt with authorization, retention and corruption handling")]),e("tr",null,[e("td",null,"Knowledge review"),e("td",null,[t("Historical "),e("code",null,"knowledge_graph.rs"),t(": candidates, evidence, promotion records")]),e("td",null,"Preserve the lifecycle; redesign identity, claims and atomic publication")]),e("tr",null,[e("td",null,"Worker contract"),e("td",null,[t("Current "),e("code",null,"lib/ordo/executor.ts"),t(" plus owner-only executor lab")]),e("td",null,"Specify one versioned contract; do not copy inconsistent envelopes unchanged")]),e("tr",null,[e("td",null,"Live interface"),e("td",null,"Current Rust gateway plus the streaming workshop"),e("td",null,"Keep adapter boundaries and batching; repair byte framing, termination and cancellation")]),e("tr",null,[e("td",null,"UI projections"),e("td",null,[t("Current "),e("code",null,"lib/ordo/projection.ts")]),e("td",null,"Keep explicit schema, visibility and limitations; replace timestamp/count cursors")]),e("tr",null,[e("td",null,"Media and import steps"),e("td",null,"Owner-only executor lab"),e("td",null,"Review specific executors for later extraction; no private source in this public site")]),e("tr",null,[e("td",null,"Hosting"),e("td",null,"Existing server studio and application release lessons"),e("td",null,"Reuse operational tests; do not reinstall over an uninspected host")])])],-1)])]),_:1}),a[3]||(a[3]=o('<h2 id="read-in-this-order" tabindex="-1">Read in this order <a class="header-anchor" href="#read-in-this-order" aria-label="Permalink to &quot;Read in this order&quot;">​</a></h2><ol><li><a href="./source-audit">Source audit</a>: what exists, what was inspected, and why it matters.</li><li><a href="./harvest-plan">Harvest plan</a>: how to turn those sources into small, maintainable modules.</li><li><a href="./../engineering/twelve-factor">Twelve-factor design</a>: operational boundaries and explicit exceptions.</li><li><a href="./../engineering/examples">Executable examples</a>: small, synthetic failure cases that clarify the contracts.</li><li><a href="./../project/roadmap">Delivery roadmap</a>: dependency-ordered slices and acceptance evidence.</li></ol><h2 id="keep-adapt-replace-defer" tabindex="-1">Keep, adapt, replace, defer <a class="header-anchor" href="#keep-adapt-replace-defer" aria-label="Permalink to &quot;Keep, adapt, replace, defer&quot;">​</a></h2><p>Make the decision for one behavior at a time. Reusing how a donor claims a job can be sensible while replacing how it stores events. Record the part to keep, the changed assumption and the test that would demonstrate the behavior in the new application.</p><p><strong>Keep</strong> means preserve a behavior and its tests after confirming dependencies and reuse rights. <strong>Adapt</strong> means retain the idea but change a boundary or invariant. <strong>Replace</strong> means the existing mechanism conflicts with this project&#39;s requirements. <strong>Defer</strong> means useful later, not required to prove the first workflow.</p><p>The priorities are not a wholesale rewrite of Ordo&#39;s business product. We do not import payments, CRM, growth accounting, public marketing shells, or broad autonomous command execution. The first useful result remains: import reports, resolve ambiguous mentions, review claims, publish a library, and answer with inspectable evidence.</p><h2 id="evidence-levels" tabindex="-1">Evidence levels <a class="header-anchor" href="#evidence-levels" aria-label="Permalink to &quot;Evidence levels&quot;">​</a></h2><p>This audit is a scoped static inspection, not a production security assessment or a claim that all donor tests passed. A source file containing a test is different from a test executed in this project. The new documentation examples exercise selected invariants; they are not the application runtime. <a href="./../status">Status</a> and actual CI runs distinguish those claims.</p><p>Private donor paths are owner-only references. Public CI must work without private repositories, provider credentials or the owner&#39;s research data. No license change, private-code publication, DNS cutover or server deployment is authorized by this audit.</p>',9))])}const x=l(p,[["render",h]]);export{y as __pageData,x as default};
